mapper.select:
WITH RECURSIVE dept_tree AS (
SELECT d.DEPARTMENT_ID, d.DEPARTMENT_CODE, d.DEPARTMENT_NAME, d.PARENT_CODE, d.SORT_ORDER, d.USE_YN, d.CREATED_AT, d.CREATED_BY, d.UPDATED_AT, d.UPDATED_BY, d.LAST_SYNCED_AT, 0 AS LEVEL, CAST(d.DEPARTMENT_CODE AS CHAR(500)) AS PATH, CAST(LPAD(d.SORT_ORDER, 5, '0') AS CHAR(500)) AS SORT_PATH FROM TB_DEPARTMENT d WHERE d.PARENT_CODE IS NULL
AND d.USE_YN = #{useYn}
UNION ALL
SELECT d.DEPARTMENT_ID, d.DEPARTMENT_CODE, d.DEPARTMENT_NAME, d.PARENT_CODE, d.SORT_ORDER, d.USE_YN, d.CREATED_AT, d.CREATED_BY, d.UPDATED_AT, d.UPDATED_BY, d.LAST_SYNCED_AT, t.LEVEL + 1, CONCAT(t.PATH, '/', d.DEPARTMENT_CODE), CONCAT(t.SORT_PATH, '/', LPAD(d.SORT_ORDER, 5, '0')) FROM TB_DEPARTMENT d INNER JOIN dept_tree t ON d.PARENT_CODE = t.DEPARTMENT_CODE
WHERE d.USE_YN = #{useYn}
) SELECT dt.DEPARTMENT_ID, dt.DEPARTMENT_CODE, dt.DEPARTMENT_NAME, dt.PARENT_CODE, dt.SORT_ORDER, dt.USE_YN, dt.CREATED_AT, dt.CREATED_BY, dt.UPDATED_AT, dt.UPDATED_BY, dt.LAST_SYNCED_AT, dt.LEVEL, dt.PATH, p.DEPARTMENT_NAME AS PARENT_NAME, (SELECT COUNT(*) FROM TB_DEPARTMENT c WHERE c.PARENT_CODE = dt.DEPARTMENT_CODE) AS CHILD_COUNT, (SELECT COUNT(*) FROM TB_USER u WHERE u.DEPARTMENT_CODE = dt.DEPARTMENT_CODE) AS USER_COUNT FROM dept_tree dt LEFT JOIN TB_DEPARTMENT p ON dt.PARENT_CODE = p.DEPARTMENT_CODE ORDER BY dt.SORT_PATH


WHERE d.PARENT_CODE IS NULL

    AND d.USE_YN = #{useYn}

ORDER BY d.SORT_ORDER

WITH RECURSIVE descendants AS ( SELECT d.DEPARTMENT_ID, d.DEPARTMENT_CODE, d.DEPARTMENT_NAME, d.PARENT_CODE, d.SORT_ORDER, d.USE_YN, d.CREATED_AT, d.CREATED_BY, d.UPDATED_AT, d.UPDATED_BY, d.LAST_SYNCED_AT, 1 AS LEVEL, CAST(d.DEPARTMENT_CODE AS CHAR(500)) AS PATH FROM TB_DEPARTMENT d WHERE d.PARENT_CODE = #{departmentCode}
UNION ALL
SELECT d.DEPARTMENT_ID, d.DEPARTMENT_CODE, d.DEPARTMENT_NAME, d.PARENT_CODE, d.SORT_ORDER, d.USE_YN, d.CREATED_AT, d.CREATED_BY, d.UPDATED_AT, d.UPDATED_BY, d.LAST_SYNCED_AT, ds.LEVEL + 1, CONCAT(ds.PATH, '/', d.DEPARTMENT_CODE) FROM TB_DEPARTMENT d INNER JOIN descendants ds ON d.PARENT_CODE = ds.DEPARTMENT_CODE ) SELECT ds.DEPARTMENT_ID, ds.DEPARTMENT_CODE, ds.DEPARTMENT_NAME, ds.PARENT_CODE, ds.SORT_ORDER, ds.USE_YN, ds.CREATED_AT, ds.CREATED_BY, ds.UPDATED_AT, ds.UPDATED_BY, ds.LAST_SYNCED_AT, ds.LEVEL, ds.PATH, p.DEPARTMENT_NAME AS PARENT_NAME, (SELECT COUNT(*) FROM TB_DEPARTMENT c WHERE c.PARENT_CODE = ds.DEPARTMENT_CODE) AS CHILD_COUNT, (SELECT COUNT(*) FROM TB_USER u WHERE u.DEPARTMENT_CODE = ds.DEPARTMENT_CODE) AS USER_COUNT FROM descendants ds LEFT JOIN TB_DEPARTMENT p ON ds.PARENT_CODE = p.DEPARTMENT_CODE ORDER BY ds.PATH

WITH RECURSIVE ancestors AS ( SELECT d.DEPARTMENT_ID, d.DEPARTMENT_CODE, d.DEPARTMENT_NAME, d.PARENT_CODE, d.SORT_ORDER, d.USE_YN, d.CREATED_AT, d.CREATED_BY, d.UPDATED_AT, d.UPDATED_BY, d.LAST_SYNCED_AT, 0 AS LEVEL FROM TB_DEPARTMENT d WHERE d.DEPARTMENT_CODE = #{departmentCode}
UNION ALL
SELECT d.DEPARTMENT_ID, d.DEPARTMENT_CODE, d.DEPARTMENT_NAME, d.PARENT_CODE, d.SORT_ORDER, d.USE_YN, d.CREATED_AT, d.CREATED_BY, d.UPDATED_AT, d.UPDATED_BY, d.LAST_SYNCED_AT, a.LEVEL + 1 FROM TB_DEPARTMENT d INNER JOIN ancestors a ON d.DEPARTMENT_CODE = a.PARENT_CODE ) SELECT a.DEPARTMENT_ID, a.DEPARTMENT_CODE, a.DEPARTMENT_NAME, a.PARENT_CODE, a.SORT_ORDER, a.USE_YN, a.CREATED_AT, a.CREATED_BY, a.UPDATED_AT, a.UPDATED_BY, a.LAST_SYNCED_AT, a.LEVEL, p.DEPARTMENT_NAME AS PARENT_NAME FROM ancestors a LEFT JOIN TB_DEPARTMENT p ON a.PARENT_CODE = p.DEPARTMENT_CODE WHERE a.DEPARTMENT_CODE != #{departmentCode} ORDER BY a.LEVEL DESC

SELECT EXISTS (
    SELECT 1 FROM TB_DEPARTMENT WHERE DEPARTMENT_CODE = #{departmentCode}
)

SELECT EXISTS (
    SELECT 1 FROM TB_DEPARTMENT
    WHERE DEPARTMENT_CODE = #{departmentCode}
      AND DEPARTMENT_ID != #{departmentId}
)

SELECT EXISTS (
    SELECT 1 FROM TB_DEPARTMENT WHERE PARENT_CODE = #{departmentCode}
)

SELECT EXISTS (
    SELECT 1 FROM TB_USER WHERE DEPARTMENT_CODE = #{departmentCode}
)

SELECT COALESCE(MAX(SORT_ORDER), 0) FROM TB_DEPARTMENT WHERE
PARENT_CODE = #{parentCode}
PARENT_CODE IS NULL

mapper.update:
UPDATE TB_DEPARTMENT
SET SORT_ORDER = SORT_ORDER + 1
WHERE


        PARENT_CODE = #{parentCode}


        PARENT_CODE IS NULL


AND SORT_ORDER >= #{fromOrder}
